let scrblrs = [];
const COLS = createCols("https://coolors.co/242220-ff6a45-ffb094-7934ad-1bc4b6-6a7a5b");

function setup()
{
  createCanvas(windowWidth, windowHeight);
  background(0);

  for(let i=0; i < 75; i++)
  {
    scrblrs.push(new Scribbler(width/2, height /2));
  }
}

function draw()
{
	background(COLS[0]);
	for(const scrblr of scrblrs){
		scrblr.update();
		scrblr.display();
	}

}



class Scribbler
{
	constructor(x, y)
	{
    this.cX = x;
    this.cY = y;
		this.minRadius = 25;
		this.maxRadius = max(width, height) * 0.4;

		this.isMovingAngle = false;
		this.radius = random(this.minRadius, this.maxRadius);
		this.angle = random(TWO_PI);
		this.angleV = 0;
		this.radiusV = 0;
    this.randomVelocities();

    this.strokeW = random(1,2.5);
    this.strokeC = COLS[floor(random(1,COLS.length))];

		this.cache = [];
		this.cacheCapacity = 120;

		this.cycle = floor(random(200,300));
		this.rotateAngle = random(TAU);
		this.rotateAngleTarget = this.rotateAngle + random(-1, 1);
		this.ratio = 0;
		this.frameOffset = floor(random(this.cycle));
	}


  update()
  {
		//pos
    let curX = (cos(this.angle) * this.radius);
    let curY = (sin(this.angle) * this.radius);
    this.cache.push(createVector(curX,curY));
		if(this.cache.length > this.cacheCapacity) this.cache.shift();

		//param
    if(this.isMovingAngle)
    {
      this.angle += this.angleV;
    }
    else 
    {
			if(this.radius < this.minRadius && this.radiusV < 0)this.radius += 0;
			else this.radius += this.radiusV * (1 + this.radius * 0.005);
    }
    if(random(1) > 0.9)
    {
       this.swapMode();
    }

		//time
		const count = frameCount + this.frameOffset;
		const cycleRatio = (count % this.cycle) / this.cycle;
		const cycleRatioMult = min(cycleRatio * 4, 1);
		const cycleRatioEased = easingEaseInOutCubic(cycleRatioMult);
		this.ratio = cycleRatioEased;
		if(count % this.cycle == 0){
			this.rotateAngle = this.rotateAngleTarget;
			this.rotateAngleTarget = this.rotateAngle + random(-1, 1);
		}
  }

	display()
	{
		let rotateAngle =  lerp(this.rotateAngle, this.rotateAngleTarget, this.ratio);
		let vertRatio =  1 + sin((this.ratio) * TAU) * 0.01;
		stroke(this.strokeC);
		strokeWeight(this.strokeW);
		noFill();
		push();
		translate(this.cX, this.cY);
		rotate(rotateAngle);
		beginShape();
		for(const p of this.cache){
			vertex(p.x * vertRatio, p.y* vertRatio);
		}
		endShape();
		pop();
	}

  swapMode()
  {
     this.isMovingAngle = !this.isMovingAngle;
     this.randomVelocities();
  }

  randomVelocities()
  {
		const angleSP = 0.05;
		const radiusSP = 2;
    this.angleV = random() > 0.5 ? random(-angleSP, -angleSP * 0.1) : random(angleSP, angleSP * 0.1) ;
		if(this.radius < this.minRadius)this.radiusV =  random(radiusSP * 0.1, radiusSP);
		else if(this.radius > this.maxRadius)this.radiusV =  random(-radiusSP, -radiusSP * 0.1);
		else this.radiusV = random() > 0.5 ? random(radiusSP * 0.1, radiusSP) : random(-radiusSP, -radiusSP * 0.1);
  }
}


function easingEaseInOutCubic (x) {
	if(x < 0.5)return 0.5 * pow(2*x, 3);
	else return 0.5 * pow(2*(x-1), 3) + 1;
}

function createCols(_url)
{
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

